//! Source and decoded template Text DOMStrings have independent admission.
use super::*;
fn fixture()->(Document,Forms,Page){
 let mut d=crate::html::parse_loaded_document_with_scripting("<body><template id=host>Held</template><template id=outer><template id=nested>Nested</template></template><input id=neighbor value=seed><p id=out>Real</p>",true,&||Ok(())).unwrap();let mut f=Forms::new(&d);let mut p=Page::new();assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)
}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
fn refusal(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str)->String{let source=format!("var failure=null;try{{{s}}}catch(e){{failure=e.name+': '+e.message;}}");match p.runtime.execute(&source,&mut Bridge{doc:d,forms:f,state:&mut p.state}){Err(e)=>e,Ok(_)=>{let Value::String(e)=p.runtime.execute("failure",&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap()else{panic!("Expected refusal: {s}")};e}}}
#[test]
fn template_output_unobserved_decoded_text_refusal_keeps_actual_content_identity(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var host=document.getElementById('host'),content=host.content,old=content.firstChild,source='&nGt;';");let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;let strings=p.state.limits.host.string_bytes;p.state.limits.host.string_bytes=5;
 let e=refusal(&mut d,&mut f,&mut p,"host.innerHTML=source;");assert!(e.contains("Decoded HTML Text"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);assert_eq!(f.controls.len(),1);p.state.limits.host.string_bytes=strings;p.begin_job();
 run(&mut d,&mut f,&mut p,"if(host.content!==content||content.firstChild!==old||old.parentNode!==content||old.data!=='Held')throw 'no decoded template prefix';host.innerHTML='Recovered&amp;';if(content.firstChild.data!=='Recovered&'||old.parentNode!==null||document.getElementById('neighbor').value!=='seed')throw 'fresh decoded template recovery';");assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_image_changes().2.is_empty());
}
#[test]
fn template_output_nested_observation_preflight_refuses_decoded_text_before_publication(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var host=document.getElementById('outer').content.firstChild,content=host.content,old=content.firstChild,owner=content.ownerDocument,source='&nGt;',watch=new MutationObserver(function(){});watch.observe(content,{childList:true});");let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;let strings=p.state.limits.host.string_bytes;p.state.limits.host.string_bytes=5;
 let e=refusal(&mut d,&mut f,&mut p,"host.innerHTML=source;");assert!(e.contains("Decoded HTML Text"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.state.limits.host.string_bytes=strings;p.begin_job();
 run(&mut d,&mut f,&mut p,"if(host.content!==content||content.ownerDocument!==owner||content.firstChild!==old||old.parentNode!==content||old.data!=='Nested'||watch.takeRecords().length)throw 'nested decoded refusal keeps actual tree';host.innerHTML='Fresh&amp;';var text=content.firstChild,records=watch.takeRecords();if(text.data!=='Fresh&'||text===old||text.ownerDocument!==owner||old.parentNode!==null||records.length!==1||records[0].target!==content||records[0].addedNodes[0]!==text||records[0].removedNodes[0]!==old)throw 'actual replacement identities after refusal';");
}
#[test]
fn template_output_exact_decoded_boundary_and_raw_source_guard_remain_independent(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var host=document.getElementById('host'),content=host.content,source='&nGt;',raw='\\udfff\\ud800';");let strings=p.state.limits.host.string_bytes;p.state.limits.host.string_bytes=6;run(&mut d,&mut f,&mut p,"host.innerHTML=source;");p.state.limits.host.string_bytes=strings;p.begin_job();run(&mut d,&mut f,&mut p,"var old=content.firstChild;if(old.data!=='\\u226b\\u20d2'||old.data.length!==2)throw 'exact decoded template boundary';");
 let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.state.limits.host.string_bytes=5;let e=refusal(&mut d,&mut f,&mut p,"host.innerHTML=source;");assert!(e.contains("Decoded HTML Text"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.state.limits.host.string_bytes=strings;p.begin_job();let e=refusal(&mut d,&mut f,&mut p,"host.innerHTML=raw;");assert!(e.contains("UTF-16"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);p.begin_job();run(&mut d,&mut f,&mut p,"if(content.firstChild!==old||old.data!=='\\u226b\\u20d2')throw 'raw template source guard kept';");
}
#[test]
fn template_output_completed_author_effects_and_captured_real_records_survive_refusal(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var host=document.getElementById('outer').content.firstChild,content=host.content,old=content.firstChild,out=document.getElementById('out'),calls=0,captured=null,watch=new MutationObserver(function(){});watch.observe(out,{childList:true});var source={toString:function(){calls++;out.textContent='X';captured=watch.takeRecords();return '&nGt;';}};");let strings=p.state.limits.host.string_bytes;p.state.limits.host.string_bytes=5;
 let e=refusal(&mut d,&mut f,&mut p,"host.innerHTML=source;");assert!(e.contains("Decoded HTML Text"),"{e}");p.state.limits.host.string_bytes=strings;p.begin_job();run(&mut d,&mut f,&mut p,"if(calls!==1||out.textContent!=='X'||host.content!==content||content.firstChild!==old||old.parentNode!==content||old.data!=='Nested'||captured.length!==1||captured[0].target!==out||captured[0].addedNodes[0]!==out.firstChild||watch.takeRecords().length)throw 'completed author effects and actual record retained';host.innerHTML='Fresh';if(content.firstChild.data!=='Fresh'||old.parentNode!==null)throw 'author effects recovery';");assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());assert!(p.take_image_changes().2.is_empty());
}
